pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }
    function testRegression_property() public {
        address tokenAddr = address(new Token());
        address from = address(0x123);
        address to1 = address(0x456);
        address to2 = address(0x789);
        address[] memory tos = new address[](2);
        tos[0] = to1;
        tos[1] = to2;
        uint v = 100;
        Token(tokenAddr).mint(from, 200);
        bool success = c.transfer(from, tokenAddr, tos, v);
        assertEq(Token(tokenAddr).balanceOf(to1), v);
        assertEq(Token(tokenAddr).balanceOf(to2), v);
    }
}

contract Token {
    mapping(address => uint256) public balanceOf;
    function mint(address to, uint256 amount) public {
        balanceOf[to] += amount;
    }
    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        require(balanceOf[from] >= amount);
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
